import React, { useRef, useState, useEffect } from 'react';
import { FaCamera, FaDownload, FaTimes, FaMobileAlt, FaDesktop } from 'react-icons/fa';

interface ExportLayoutProps {
  width: string;
  label: string;
}

const ExportLayout: React.FC<ExportLayoutProps> = ({ width, label }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [html2canvas, setHtml2canvas] = useState<any>(null);
  const isMobile = width === '390px';

  useEffect(() => {
    // Dynamically import html2canvas to avoid SSR issues
    if (typeof window !== 'undefined') {
      import('html2canvas').then((module) => {
        setHtml2canvas(() => module.default);
      });
    }
  }, []);

  const handleExport = async () => {
    if (!iframeRef.current || !html2canvas) return;
    
    setIsExporting(true);

    try {
      const iframe = iframeRef.current;
      const iframeDoc = iframe.contentDocument || iframe.contentWindow?.document;

      if (!iframeDoc) {
        throw new Error("Unable to access iframe document.");
      }

      // Inject temporary styles into iframe to ensure full height and no scrollbars during capture
      const style = iframeDoc.createElement("style");
      style.innerHTML = `
        ::-webkit-scrollbar { display: none !important; }
        html, body { 
          height: auto !important; 
          overflow: visible !important; 
          background: #ffffff !important;
        }
        /* Hide export-specific UI elements inside the frame if any */
        .export-controls, .btn-load-more, .lightbox-overlay {
          display: none !important;
        }
        /* Disable all animations and transitions */
        * {
          animation: none !important;
          transition: none !important;
          animation-delay: 0s !important;
        }
      `;
      iframeDoc.head.appendChild(style);

      const target = iframeDoc.body;

      // Wait for images and fonts to settle
      await new Promise((r) => setTimeout(r, 1200));

      const canvas = await html2canvas(target, {
        scale: 2,
        useCORS: true,
        allowTaint: true,
        backgroundColor: "#ffffff",
        width: target.scrollWidth,
        height: target.scrollHeight,
        logging: false,
      });

      const image = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.href = image;
      link.download = `${label.toLowerCase()}-export-${Date.now()}.png`;
      link.click();

      // Cleanup styles
      iframeDoc.head.removeChild(style);
    } catch (err) {
      console.error('Export failed:', err);
      alert('Export failed. Check console.');
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="export-page-container" style={{ 
      background: "var(--color-secondary)", 
      minHeight: "100vh", 
      paddingBottom: "80px",
      fontFamily: "'Inter', sans-serif"
    }}>
      <style>{`
        .export-top-bar {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          z-index: 10000;
          background: rgba(0,0,0,0.85);
          backdrop-filter: blur(15px);
          padding: 15px 40px;
          display: flex;
          justify-content: space-between;
          align-items: center;
          border-bottom: 1px solid rgba(255,255,255,0.1);
        }
        .export-btn {
          background: var(--color-primary);
          color: #fff;
          border: none;
          padding: 10px 25px;
          border-radius: 6px;
          font-weight: 800;
          font-size: 0.95rem;
          cursor: pointer;
          display: flex;
          align-items: center;
          gap: 10px;
          transition: 0.3s;
          box-shadow: 0 4px 15px rgba(255, 117, 48, 0.3);
        }
        .export-btn:hover:not(:disabled) {
          background: var(--color-primary-light);
          transform: translateY(-2px);
          box-shadow: 0 8px 25px rgba(255, 117, 48, 0.4);
        }
        .export-btn:disabled {
          background: #444;
          color: #888;
          cursor: not-allowed;
          box-shadow: none;
        }
        .close-link {
          color: #fff;
          font-size: 1.5rem;
          opacity: 0.6;
          transition: 0.3s;
        }
        .close-link:hover { opacity: 1; }
        .frame-container {
          display: flex;
          justify-content: center;
          align-items: flex-start;
          padding-top: 100px;
        }
        .device-frame {
          position: relative;
          background: #fff;
          box-shadow: 0 40px 120px rgba(0,0,0,0.6);
          border-radius: ${isMobile ? '32px' : '12px'};
          overflow: hidden;
          border: ${isMobile ? '12px solid #222' : '4px solid #333'};
          transition: 0.5s cubic-bezier(0.165, 0.84, 0.44, 1);
        }
        .brand-accent {
          color: var(--color-primary);
        }
      `}</style>

      <div className="export-top-bar">
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
          {isMobile ? <FaMobileAlt className="brand-accent" style={{ fontSize: '1.4rem' }} /> : <FaDesktop className="brand-accent" style={{ fontSize: '1.2rem' }} />}
          <span style={{ color: '#fff', fontWeight: 700, fontSize: '1.1rem' }}>{label} Proposal Preview</span>
        </div>
        
        <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
          <button 
            className="export-btn" 
            onClick={handleExport}
            disabled={isExporting || !html2canvas}
          >
            {isExporting ? <FaCamera /> : <FaDownload />} 
            {isExporting ? 'Capturing Full Page...' : `Capture ${label} Image`}
          </button>
          <a href="/" className="close-link"><FaTimes /></a>
        </div>
      </div>

      <div className="frame-container">
        <div className="device-frame" style={{ 
          width: width, 
          height: isMobile ? '780px' : '850px'
        }}>
          <iframe
            ref={iframeRef}
            src="/"
            title="preview"
            style={{
              width: '100%',
              height: '100%',
              border: "none",
              background: '#fff'
            }}
          />
        </div>
      </div>
      
      <div style={{ textAlign: 'center', marginTop: '40px', color: 'rgba(255,255,255,0.4)', fontSize: '0.9rem' }}>
        Tip: The capture will include the entire page, not just the visible area in the frame.
      </div>
    </div>
  );
};

export default ExportLayout;
